CREATE OR REPLACE FUNCTION test_trigger_func()
        RETURNS TRIGGER AS $$
        BEGIN
            NEW.updated_at = NOW();
            RETURN NEW;
        END

CREATE OR REPLACE PROCEDURE complex_proc()
        LANGUAGE SQL
        BEGIN
            DECLARE v_error_code INTEGER DEFAULT 0;

            DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
            BEGIN
                SET v_error_code = 1;
                ROLLBACK;
            END;

            BEGIN ATOMIC
                INSERT INTO test VALUES (1);
                INSERT INTO test VALUES (2);
            END;

            IF v_error_code = 0 THEN
                COMMIT;
            END IF;
        END

CREATE OR REPLACE PROCEDURE safe_insert(IN val INTEGER)
LANGUAGE SQL
BEGIN
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
    END;
    INSERT INTO t VALUES (val);
    COMMIT;
END

